```typescript
import { createServer, type Server } from 'node:http';
import { randomBytes } from 'node:crypto';
import fs from 'node:fs';
import vm from 'node:vm';
import type { SharedState } from '@/backend/execution/flow/types';

// Deterministic node execution, with production lifecycle/scheduler/HTTP/archive code.
jest.mock('@/utils/logger', () => ({ createLogger: () => ({ debug() {}, info() {}, warn() {}, error() {}, verbose() {} }) }));
jest.mock('@/backend/execution/flow/handlers/ModelHandler', () => ({
  ModelHandler: { processToolCalls: jest.fn(async () => ({ success: true, value: { toolCallMessages: [], processedToolCalls: [] } })) },
}));
jest.mock('@/backend/execution/flow/FlowExecutor', () => ({ FlowExecutor: {
  conversationStates: new Map(), clearFlowCache: jest.fn(),
  executeStep: (state: SharedState) => executeFixtureStep(state),
  resolveHandoff: async (state: SharedState, action: string) => ({
    isSuccessorEdge: state.currentNodeId === 'start' && action === 'start->process',
    targetNodeId: state.currentNodeId === 'start' && action === 'start->process' ? 'process' : null,
  }),
  peekNextNodeId: async (state: SharedState) => state.currentNodeId ?? 'start',
} }));
const graph = { id: 'issue520', name: 'Issue 520', nodes: [{ id: 'start', type: 'start' }, { id: 'process', type: 'process' }],
  edges: [{ source: 'start', target: 'process', type: 'custom', data: { edgeType: 'standard' } }] };
jest.mock('@/backend/services/flow/index', () => ({ flowService: { loadFlows: async () => [graph], getFlow: async () => graph } }));
jest.mock('@/backend/execution/flow/validateFlowForRun', () => ({ validateFlowForRun: async () => ({ issues: [], errorCount: 0, warningCount: 0, isRunnable: true }) }));

import { runFlow } from '@/backend/execution/flow/runFlow';
import { runSubflowLanes } from '@/backend/execution/flow/nodes/SubflowNode';
import { FlowExecutor } from '@/backend/execution/flow/FlowExecutor';
import { getConversationCacheDiagnostics, _resetConversationCacheForTests } from '@/backend/execution/flow/conversationStateCache';
import { _setModelTurnArchiveDirForTests, archiveModelDispatch, updateModelDispatchOutcome, deleteModelTurnArchive, readModelTurnSnapshot } from '@/backend/execution/flow/modelTurnArchive';
import { OpenAiAdapter } from '@/backend/services/model/adapters/openaiAdapter';
import { isTransientTransportError } from '@/backend/utils/transientRetry';

const adapter = new OpenAiAdapter();
const requests: Record<string, number> = {};
const recoveredIds = new Set<string>();
let archived = 0;
let archiveVerified = 0;
const archiveMismatches: string[] = [];
let server: Server;
let baseUrl = '';
let activeLanes = 0;
let maxActiveLanes = 0;
const statuses: Record<string, number> = {};
const gc = vm.runInNewContext('gc') as () => void;
const samples: Record<string, unknown>[] = [];
const report: Record<string, any> = { commit: process.env.TEST_COMMIT, variant: process.env.TEST_VARIANT, node: process.version,
  parameters: { batches: Number(process.env.STRESS_BATCHES ?? 12), lanes: 8, concurrency: 4, parentChars: 2_000_000,
    childChars: [3_600_000, 4_000_000, 4_800_000, 5_600_000], tokenSizing: '4 ASCII characters per proxy token; no tokenizer or paid model' } };
let peakRss = 0;
let peakHeap = 0;
function sample(label: string) {
  const memory = process.memoryUsage();
  peakRss = Math.max(peakRss, memory.rss); peakHeap = Math.max(peakHeap, memory.heapUsed);
  if (label !== 'interval') samples.push({ label, ...memory, cache: getConversationCacheDiagnostics(), states: FlowExecutor.conversationStates.size });
}
function transcript(chars: number, prefix: string) {
  const messages: any[] = [];
  for (let offset = 0; offset < chars; offset += 16_000) {
    const length = Math.min(16_000, chars - offset);
    messages.push({ id: `${prefix}-${offset}`, role: offset % 32_000 ? 'assistant' : 'user',
      content: randomBytes(Math.ceil(length * 3 / 4) + 1).toString('base64').slice(0, length), timestamp: Date.now() });
  }
  return messages;
}

async function executeFixtureStep(state: SharedState) {
  state.currentNodeId ??= 'start';
  if (state.currentNodeId === 'start') return { sharedState: state, action: 'start->process' };
  const kind = recoveredIds.has(state.conversationId!) ? 'complete' : String(state.conversationId).includes('bad400') ? 'bad400' : String(state.conversationId).includes('cap') ? 'cap' : 'complete';
  const phase = state.forceSummaryTurn ? 'summary' : 'normal';
  const key = `${state.conversationId}:${kind}:${phase}`;
  const wire = state.messages.map(message => ({ role: message.role, content: message.content,
    ...(message.tool_calls ? { tool_calls: message.tool_calls } : {}),
    ...('tool_call_id' in message ? { tool_call_id: message.tool_call_id } : {}) }));
  try {
    const result = await adapter.createCompletion({
      model: { id: 'fixture', name: key, provider: 'openrouter', adapter: 'openai', baseUrl, contextWindow: 2_000_000 } as any,
      apiKey: 'docker-local-fixture-only', messages: wire as any,
      tools: [{ type: 'function', function: { name: 'some_tool', parameters: { type: 'object', properties: {} } } }],
      onSdkRequest: async snapshot => {
        // Match the clone/serialization workload of ModelHandler's dispatch hook.
        const entry = await archiveModelDispatch({ conversationId: state.conversationId!, runId: state.logicalRunId,
          nodeId: 'process', modelId: 'fixture', modelName: key, adapter: snapshot.adapter,
          operation: snapshot.operation, attempt: ++archived, canonicalMessages: structuredClone(state.messages),
          genericWire: structuredClone(wire) as any, sdkRequest: snapshot.request });
        return entry.id;
      },
      onSdkRequestResult: async ({ dispatchId, outcome }) => {
        await updateModelDispatchOutcome(state.conversationId!, dispatchId, outcome);
        // Readback verifies that large snapshots and outcome rewrites are valid.
        const snapshot = await readModelTurnSnapshot(state.conversationId!, dispatchId);
        if (snapshot?.entry.outcome !== outcome) archiveMismatches.push(dispatchId);
        else archiveVerified++;
      },
    });
    const message = result.completion.choices[0].message;
    state.messages.push({ ...message, id: `${key}-${state.messages.length}`, timestamp: Date.now(), processNodeId: 'process' } as any);
    state.lastResponse = message.content ?? '';
    if (message.tool_calls?.length) {
      state.turnBudgets = { process: 1 };
      return { sharedState: state, action: 'TOOL_CALL' };
    }
    return { sharedState: state, action: 'FINAL_RESPONSE' };
  } catch (error: any) {
    state.lastResponse = { success: false, error: error.message, errorDetails: { message: error.message, status: error.status } };
    return { sharedState: state, action: 'ERROR' };
  }
}

beforeAll(async () => {
  jest.setTimeout(1_200_000);
  _setModelTurnArchiveDirForTests('/tmp/issue520-archives');
  _resetConversationCacheForTests();
  server = createServer(async (request, response) => {
    const chunks = [];
    for await (const chunk of request) chunks.push(chunk);
    const body = JSON.parse(Buffer.concat(chunks).toString('utf8'));
    const key = body.model as string;
    requests[key] = (requests[key] ?? 0) + 1;
    // Ensure four lanes overlap before the scheduler claims the other four.
    await new Promise(resolve => setTimeout(resolve, 40));
    response.setHeader('content-type', 'application/json');
    if (key.includes(':bad400:')) {
      response.statusCode = 400;
      response.end(JSON.stringify({ error: { code: 400, message: 'Provider returned error - Provider returned error (upstream: AtlasCloud: {"code":400,"msg":"bad request","request_id":"fixture"})' } }));
      return;
    }
    const toolTurn = key.includes(':cap:normal');
    response.end(JSON.stringify({ id: 'fixture-completion', object: 'chat.completion', created: 1, model: key,
      choices: [{ index: 0, finish_reason: toolTurn ? 'tool_calls' : 'stop', message: toolTurn
        ? { role: 'assistant', content: '', tool_calls: [{ id: 'call_fixture', type: 'function', function: { name: 'some_tool', arguments: '{}' } }] }
        : { role: 'assistant', content: 'SUMMARY: deterministic local completion.' } }],
      usage: { prompt_tokens: 1_400_000, completion_tokens: 8, total_tokens: 1_400_008 } }));
  });
  await new Promise<void>(resolve => server.listen(0, '127.0.0.1', resolve));
  baseUrl = `http://127.0.0.1:${(server.address() as any).port}/v1`;
});

afterAll(async () => {
  report.requests = requests; report.archivedDispatches = archived; report.statuses = statuses;
  report.archiveVerified = archiveVerified; report.archiveMismatches = archiveMismatches;
  report.maxActiveLanes = maxActiveLanes; report.samples = samples; report.peakRssBytes = peakRss; report.peakHeapBytes = peakHeap;
  report.cgroupMemoryPeakBytes = Number(fs.readFileSync('/sys/fs/cgroup/memory.peak', 'utf8'));
  fs.mkdirSync('/evidence', { recursive: true });
  fs.writeFileSync(`/evidence/stress-${process.env.TEST_VARIANT}.json`, JSON.stringify(report, null, 2));
  await new Promise<void>(resolve => server.close(() => resolve()));
});

it('repeatedly drains large capped/completed/error subflows and avoids extra AtlasCloud 400 dispatches', async () => {
  const parentId = 'issue520-parent';
  FlowExecutor.conversationStates.set(parentId, { conversationId: parentId, logicalRunId: parentId, status: 'running',
    messages: transcript(2_000_000, 'parent'), flowId: 'issue520', currentNodeId: 'process' } as any);
  gc(); sample('baseline');
  const baseline = process.memoryUsage().heapUsed;
  const poll = setInterval(() => sample('interval'), 100);
  const kinds = ['cap', 'cap', 'cap', 'bad400', 'complete', 'cap', 'complete', 'cap'];
  const leaks: number[] = [];
  try {
    for (let batch = 0; batch < report.parameters.batches; batch++) {
      // Lazy per-lane input construction keeps queued jobs from allocating until admitted.
      const lanes = kinds.map((kind, index) => ({ subflowId: 'issue520', conversationId: `batch${batch}_lane${index}_${kind}`, input: { prompt: 'fixture' } }));
      const result = await runSubflowLanes({ nodeId: 'subflow', nodeType: 'subflow', subflowId: 'issue520', depth: 1,
        parentRunId: parentId, persistConversation: false, concurrencyLimit: 4, errorStrategy: 'collect-all', lanes } as any,
        async input => {
          activeLanes++; maxActiveLanes = Math.max(maxActiveLanes, activeLanes);
          try {
            const index = Number(input.conversationId!.match(/lane(\d+)/)![1]);
            const result = await runFlow({ ...input, messages: transcript(report.parameters.childChars[index % 4], input.conversationId!), prompt: undefined });
            statuses[result.status] = (statuses[result.status] ?? 0) + 1;
            return result;
          } finally { activeLanes--; }
        }, { nodeId: 'subflow', nodeType: 'subflow' }, { prompt: 'fixture' });
      expect(result.lanes).toHaveLength(8);
      expect(result.lanes!.filter(lane => !lane.success)).toHaveLength(1);
      // Archives live on disk in production; remove batch files only to bound test disk use.
      await Promise.all(lanes.map(lane => deleteModelTurnArchive(lane.conversationId)));
      gc(); sample(`batch-${batch}`);
      leaks.push(FlowExecutor.conversationStates.size - 1);
      console.log(JSON.stringify({ batch, leakedChildren: leaks[batch], heapUsed: process.memoryUsage().heapUsed, rss: process.memoryUsage().rss }));
    }
  } finally { clearInterval(poll); }
  report.leakedChildrenByBatch = leaks;
  report.retainedHeapGrowthBytes = process.memoryUsage().heapUsed - baseline;
  report.bad400RequestCounts = Object.fromEntries(Object.entries(requests).filter(([key]) => key.includes(':bad400:')));
  expect(maxActiveLanes).toBe(4);
  expect(Object.values(report.bad400RequestCounts).every(count => count === 1)).toBe(true);
  expect(leaks.every(count => count === 0)).toBe(true);
  expect(getConversationCacheDiagnostics().entries).toBe(0);
  expect(archiveMismatches).toHaveLength(0);
  expect(archiveVerified).toBe(archived);
  expect(report.retainedHeapGrowthBytes).toBeLessThan(128 * 1024 * 1024);
}, 1_200_000);

it('rejects a 400 whose message contains a transient keyword', () => {
  expect(isTransientTransportError(Object.assign(new Error('503 service unavailable'), { status: 400 }))).toBe(false);
});

it('continues a persisted conversation after the provider 400 without replaying the failed request', async () => {
  const conversationId = 'recovery_bad400';
  const messages = transcript(5_600_000, 'recovery');
  const failed = await runFlow({ flowId: 'issue520', conversationId, mode: 'conversation', source: 'api', messages });
  expect(failed.status).toBe('error');
  expect(requests[`${conversationId}:bad400:normal`]).toBe(1);
  recoveredIds.add(conversationId);
  const continued = await runFlow({ flowId: 'issue520', conversationId, mode: 'conversation', source: 'api',
    resumeAsNewTurn: true, messages: [{ role: 'user', content: 'Continue after the failed provider request.' }] });
  expect(continued.status).toBe('completed');
  expect(requests[`${conversationId}:complete:normal`]).toBe(1);
  expect(continued.messages.some(message => message.content === messages[0].content)).toBe(true);
  report.continuation = { failedStatus: failed.status, continuedStatus: continued.status,
    failedRequestAttempts: requests[`${conversationId}:bad400:normal`], continuedRequestAttempts: requests[`${conversationId}:complete:normal`] };
}, 120_000);

