```javascript
const fs = require('node:fs');
const crypto = require('node:crypto');
const edits = [];
function change(file, transform) {
  const original = fs.readFileSync(file, 'utf8');
  const changed = transform(original);
  if (changed === original) throw new Error(`Negative control did not change ${file}`);
  fs.writeFileSync(file, changed);
  edits.push({ file, before: crypto.createHash('sha256').update(original).digest('hex'),
    after: crypto.createHash('sha256').update(changed).digest('hex') });
}
change('/app/src/backend/execution/flow/runFlow.ts', text => {
  const start = text.indexOf('const cleanupEphemeral = () => {');
  if (start < 0) throw new Error('Missing cleanupEphemeral');
  const end = text.indexOf('\n  };', start);
  const block = text.slice(start, end);
  const changed = block.replace(/sharedState\.status === 'error' \|\|\r?\n\s*sharedState\.status === 'capped'/, "sharedState.status === 'error'");
  if (changed === block) throw new Error('Capped cleanup hunk not found');
  return text.slice(0, start) + changed + text.slice(end);
});
change('/app/src/backend/utils/transientRetry.ts', text => {
  const eol = text.includes('\r\n') ? '\r\n' : '\n';
  const status = "  const status = (error as Error & { status?: unknown }).status;" + eol
    + "  if (typeof status === 'number' && status >= 400 && status < 500) return false;" + eol;
  if (!text.includes(status)) throw new Error('4xx gate hunk not found');
  if (!text.includes("  'bad gateway',")) throw new Error('Keyword insertion point not found');
  return text.replace(status, '').replace("  'bad gateway',", "  'upstream error'," + eol + "  'provider returned error'," + eol + "  'bad gateway',");
});
fs.mkdirSync('/evidence', { recursive: true });
fs.writeFileSync('/evidence/control-mutations.json', JSON.stringify({
  baseCommit: '3511ba49514fe8cf525f5a22c16c3806bf3886ba',
  revertedFix: '0c9506a9ba97bd7d3829cb248307b4254c199f1e', edits,
}, null, 2));

